

CREATE TABLE IF NOT EXISTS users (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    firebase_uid VARCHAR(128) NOT NULL UNIQUE,
    email VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS journal_entries (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    content JSON NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_journal_entries_user_id ON journal_entries(user_id);
-- 
ALTER TABLE users ADD COLUMN username VARCHAR(50) UNIQUE;
ALTER TABLE users ADD COLUMN settings JSON;
ALTER TABLE journal_entries RENAME TO notes;
CREATE TABLE IF NOT EXISTS connections (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    requester_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    receiver_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    status VARCHAR(20) NOT NULL DEFAULT 'pending', -- pending, accepted
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT unique_connection UNIQUE (requester_id, receiver_id),
    CONSTRAINT no_self_connection CHECK (requester_id != receiver_id)
);

CREATE INDEX idx_connections_requester ON connections(requester_id);
CREATE INDEX idx_connections_receiver ON connections(receiver_id);
CREATE TABLE IF NOT EXISTS `groups` (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    name VARCHAR(255) NOT NULL,
    description TEXT,
    created_by VARCHAR(36) REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS group_members (
    group_id VARCHAR(36) REFERENCES `groups`(id) ON DELETE CASCADE,
    user_id VARCHAR(36) REFERENCES users(id) ON DELETE CASCADE,
    role VARCHAR(50) NOT NULL DEFAULT 'member', -- 'admin', 'member'
    joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (group_id, user_id)
);

CREATE INDEX idx_groups_name ON `groups`(name);
CREATE INDEX idx_group_members_user_id ON group_members(user_id);
CREATE TABLE IF NOT EXISTS group_shares (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    group_id VARCHAR(36) REFERENCES `groups`(id) ON DELETE CASCADE,
    note_id VARCHAR(36) REFERENCES notes(id) ON DELETE CASCADE,
    shared_by VARCHAR(36) REFERENCES users(id) ON DELETE CASCADE,
    shared_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    comment TEXT,
    UNIQUE(group_id, note_id)
);

CREATE INDEX idx_group_shares_group_id ON group_shares(group_id);
CREATE TABLE IF NOT EXISTS reading_plans (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    title VARCHAR(255) NOT NULL,
    description TEXT,
    days INT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS reading_plan_days (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    reading_plan_id VARCHAR(36) NOT NULL REFERENCES reading_plans(id) ON DELETE CASCADE,
    day_number INT NOT NULL,
    passage TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(reading_plan_id, day_number)
);

CREATE TABLE IF NOT EXISTS user_reading_plans (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    reading_plan_id VARCHAR(36) NOT NULL REFERENCES reading_plans(id) ON DELETE CASCADE,
    start_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    status VARCHAR(20) NOT NULL DEFAULT 'active', -- active, completed
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS user_reading_plan_progress (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    user_reading_plan_id VARCHAR(36) NOT NULL REFERENCES user_reading_plans(id) ON DELETE CASCADE,
    day_number INT NOT NULL,
    completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_reading_plan_id, day_number)
);

CREATE INDEX idx_reading_plans_created_at ON reading_plans(created_at);
CREATE INDEX idx_user_reading_plans_user_id ON user_reading_plans(user_id);
CREATE INDEX idx_user_reading_plan_progress_plan_id ON user_reading_plan_progress(user_reading_plan_id);
ALTER TABLE notes ADD COLUMN deleted_at TIMESTAMP;
ALTER TABLE reading_plans ADD COLUMN plan_type VARCHAR(20) NOT NULL DEFAULT 'sequential';
-- M'Cheyne Reading Plan Seed
CREATE TABLE memory_verses (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    user_id VARCHAR(36) REFERENCES users(id) ON DELETE CASCADE, -- Nullable for system packs
    pack_name VARCHAR(100), -- E.g., "TMS: Living the New Life" or "My Verses"
    reference VARCHAR(100) NOT NULL,
    text TEXT NOT NULL,
    version VARCHAR(20) NOT NULL DEFAULT 'ESV',
    tags JSON,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_memory_verses_user_id ON memory_verses(user_id);
CREATE INDEX idx_memory_verses_pack_name ON memory_verses(pack_name);


-- Seed TMS Data (Topical Memory System) - A - Live the New Life
CREATE TABLE study_templates (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    creator_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    structure JSON, -- Sections like Passage, Reflection, etc.
    prompts JSON, -- AI System Prompts
    fields JSON, -- User input fields definition
    is_public BOOLEAN DEFAULT false,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_study_templates_creator_id ON study_templates(creator_id);
CREATE INDEX idx_study_templates_is_public ON study_templates(is_public);
-- Create verse_packs table
CREATE TABLE verse_packs (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    user_id VARCHAR(36) REFERENCES users(id) ON DELETE CASCADE, -- NULL for system packs
    title VARCHAR(100) NOT NULL,
    identifier VARCHAR(50), -- Increased to 50 for safety
    description TEXT,
    is_public BOOLEAN DEFAULT false,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_verse_packs_user_id ON verse_packs(user_id);
