CREATE TABLE tags (
    id VARCHAR(36) PRIMARY KEY DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name VARCHAR(50) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT unique_user_tag_name UNIQUE (user_id, name)
);

CREATE TABLE note_tags (
    note_id VARCHAR(36) NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
    tag_id VARCHAR(36) NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (note_id, tag_id)
);

CREATE INDEX idx_tags_user_id ON tags(user_id);
CREATE INDEX idx_note_tags_tag_id ON note_tags(tag_id);
-- Discipleship Journal Bible Reading Plan


-- CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX idx_notes_user_deleted_updated
    ON notes (user_id, deleted_at, updated_at DESC);

CREATE INDEX idx_notes_user_deleted_title
    ON notes (user_id, deleted_at, title);

-- DROP INDEX IF EXISTS idx_notes_title_trgm;
CREATE TABLE IF NOT EXISTS user_verse_preferences (
    user_id VARCHAR(36) NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    verse_id VARCHAR(36) NOT NULL REFERENCES memory_verses(id) ON DELETE CASCADE,
    version_override VARCHAR(50) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, verse_id)
);

CREATE INDEX idx_user_verse_preferences_user ON user_verse_preferences(user_id);
